def _valid_email(value) -> bool:
    if not isinstance(value, str):
        return False
    email = value.strip()
    if email.count("@") != 1:
        return False
    local, _, domain = email.partition("@")
    if not local:
        return False
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return False
    return True


def handle_email_available(params: dict) -> tuple[int, dict]:
